import { createClient } from '@supabase/supabase-js';
import 'dotenv/config';

const sb = createClient(process.env.SUPABASE_URL || process.env.NEXT_PUBLIC_SUPABASE_URL, process.env.SUPABASE_SERVICE_ROLE_KEY);
const SD_KEY = 'SD-LEARN-FIX-LEARNING-IMPROVEMENT-005';

// LEAD-phase correction: the SD as auto-generated by /learn carried boilerplate
// ("No description", "Implement improvement: ") because the source
// protocol_improvement_queue item (696c8014) had its description populated AFTER
// SD creation, when database-agent's live-table investigation reframed the original
// finding's premise. This replaces the boilerplate with the real, reframed scope.
const title = 'TESTING evidence provenance fields (artifact_sha/runner) have zero readers';
const description = `## Problem

lib/sub-agents/testing/test-execution-record.js's buildTestExecution() already includes
artifact_sha and runner fields on metadata.test_execution -- they are NOT missing (the
original finding this SD's source item corrected said they were). The real defect:
NOTHING in the codebase reads them. No gate, handoff validator, or query anywhere
consumes metadata.test_execution.artifact_sha or .runner. Live measurement: runner is set
on 8 rows, artifact_sha on a handful, most of those null -- write-only fields nobody checks.

This is the residual, unimplemented arm of chairman ratification 6c263823 ("Evidence
without provenance is absent, not weak"): TESTING reads only a runner-written results file
with its hash in the verdict row. SD-FDBK-INFRA-TESTING-VERDICT-ROWS-001 (this SD's own
predecessor) raised the write-time bar from prose to structured numbers, but explicitly
did NOT implement producer/hash provenance -- that gap is this SD's scope.

## What "done" looks like

A DB constraint cannot express provenance (a hash is meaningless without something to
re-read and re-hash). The deliverable is a runner-side artifact-writing contract plus a
verifier that re-reads it, spanning:
1. The TESTING sub-agent's execution path: after a real test run, write a results file to
   disk (or reuse an existing report artifact already on disk, e.g. the Playwright report),
   compute its sha256, and set metadata.test_execution.artifact_sha/.runner to the real
   values (not left null).
2. A verifier (either inline in the TESTING sub-agent, or a companion function importable
   by mandatory-testing-validation.js) that, given a stored artifact_sha, re-reads the
   artifact file and confirms the hash matches before trusting the row's counts -- the
   same "runner-written results file with its hash" contract SD-FDBK-INFRA-TESTING-SUB-
   AGENT-001 and SD-FDBK-INFRA-TESTING-EVIDENCE-REUSE-001 already built for freshness/
   artifact-shape verification (lib/sub-agents/testing/artifact-verification.js is the
   existing precedent to extend, not replace).
3. Wire the verifier into mandatory-testing-validation.js as an additional, defense-in-
   depth check alongside the existing freshness/shape checks -- a row whose artifact_sha
   does not match the artifact it claims to point at should downgrade or warn, matching
   the existing report-hash-binding pattern already documented in
   docs/03_protocols_and_standards/leo-v4.4.2-testing-governance.md.

## Explicitly out of scope
- Adding new DB columns (the fields already exist).
- Changing the write-time guard from SD-FDBK-INFRA-TESTING-VERDICT-ROWS-001 (that SD's
  scope is closed; this SD only adds provenance verification on top of it).
- Backfilling artifact_sha/runner on historical rows.`;

const scope = 'IN SCOPE: TESTING sub-agent artifact-writing (results file + sha256), a hash-verification function, and wiring it as an additional check in mandatory-testing-validation.js. OUT OF SCOPE: new DB columns (artifact_sha/runner already exist), changing the write-time test_execution guard (SD-FDBK-INFRA-TESTING-VERDICT-ROWS-001, closed), backfilling historical rows, changing gate thresholds/scoring algorithms, modifying SDs that already passed quality gates.';

const success_criteria = [
  {
    criterion: 'A real TESTING sub-agent run (mainline execution path) writes metadata.test_execution.artifact_sha as a real sha256 of an on-disk results artifact, not null',
    measure: 'A test run produces a row whose artifact_sha matches sha256(the artifact file on disk) exactly',
  },
  {
    criterion: 'A verifier re-reads the artifact and confirms the hash before the row is trusted, wired into mandatory-testing-validation.js as an additional defense-in-depth check',
    measure: 'A row whose artifact_sha does NOT match its claimed artifact is detected and downgrades/warns, not silently trusted',
    verification: 'Unit test: a forged artifact_sha (or a swapped/corrupted artifact file) is caught',
  },
  {
    criterion: 'No new DB columns added; no change to the SD-FDBK-INFRA-TESTING-VERDICT-ROWS-001 write-time guard\'s behavior for well-formed rows',
    measure: 'git diff shows zero migration files and zero changes to lib/sub-agent-executor/testing-verdict-guard.js',
    verification: 'Automated: migration file count in diff, diff of testing-verdict-guard.js',
  },
];

const { error } = await sb
  .from('strategic_directives_v2')
  .update({ title, description, scope, success_criteria })
  .eq('sd_key', SD_KEY);
if (error) throw error;
console.log('Corrected SD fields for', SD_KEY);
